package controlsys

// Round-3 lsfit probe (3PWI4Q): base-vs-branch LS C2D/C2DFit sweep over the
// reviewer sets ns400 (PCG(seed,7704), seeds 0..400) and ns1600
// (PCG(seed,9911), seeds 0..1599), plus explicit/wellE/midE (PCG(seed,31337)).
// LSR3_OUT=file writes one JSON line per case. Compiles at 60cf4cf and branch.

import (
	"encoding/json"
	"fmt"
	"hash/fnv"
	"math"
	"math/cmplx"
	"math/rand/v2"
	"os"
	"testing"
	"time"

	"plantcontrol.org/v1/gonum/mat"
)

type lsR3Row struct {
	Set, Variant    string
	Seed            uint64
	N, M, P         int
	Routed          bool
	Err, Hash       string
	Stable          bool
	FitPen          float64
	MaxPole         float64
	DOrder          int
	NormAd1         float64
	FitErr, FitHash string
	FitMax, FitRMS  float64
	Ns              float64
	OtherHash       map[string]string
}

func lsR3Hash(s *System) string {
	if s == nil {
		return ""
	}
	h := fnv.New64a()
	w := func(m *mat.Dense) {
		if m == nil {
			fmt.Fprint(h, "nil;")
			return
		}
		r, c := m.Dims()
		fmt.Fprint(h, r, c, ";")
		for i := range r {
			for j := range c {
				fmt.Fprint(h, math.Float64bits(m.At(i, j)), ",")
			}
		}
	}
	w(s.A)
	w(s.B)
	w(s.C)
	w(s.D)
	w(s.E)
	w(s.Delay)
	fmt.Fprint(h, s.Dt, s.InputDelay, s.OutputDelay)
	return fmt.Sprintf("%x", h.Sum64())
}

func lsR3Fin(v float64) float64 {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return 1e300
	}
	return v
}

// lsR3MaxErr is the reviewer metric: max over theta = pi q/200, q = 1..199,
// of |Gd(e^{j theta}) - G(j theta/dt)| / max(1, |G|), G the pencil response.
func lsR3MaxErr(t *testing.T, d *System, oracle *System, dt float64) float64 {
	worst := 0.0
	dd := d.Copy()
	dd.InputDelay, dd.OutputDelay = nil, nil
	for q := 1; q < 200; q++ {
		th := math.Pi * float64(q) / 200
		g, err := dd.EvalFr(cmplx.Exp(complex(0, th)))
		if err != nil {
			return 1e300
		}
		want := pencilResponse(t, oracle, complex(0, th/dt))
		worst = math.Max(worst, cmplx.Abs(g[0][0]-want[0][0])/math.Max(1, cmplx.Abs(want[0][0])))
	}
	return lsR3Fin(worst)
}

func lsR3Time(sys *System, dt float64, opt C2DOptions) float64 {
	best := math.Inf(1)
	for range 3 {
		t0 := time.Now()
		sys.C2D(dt, opt)
		best = math.Min(best, float64(time.Since(t0).Nanoseconds()))
	}
	return best
}

type lsR3Case struct {
	Set, Variant string
	Seed         uint64
	Sys          *System
}

func lsR3NSCases(t *testing.T) []lsR3Case {
	var out []lsR3Case
	for _, set := range []struct {
		name   string
		stream uint64
		hi     uint64
	}{{"ns400", 7704, 400}, {"ns1600", 9911, 1599}} {
		for seed := uint64(0); seed <= set.hi; seed++ {
			rng := rand.New(rand.NewPCG(seed, set.stream))
			n := 2 + rng.IntN(5)
			m, p := 1, 1
			if rng.IntN(3) == 0 {
				m, p = 1+rng.IntN(2), 1+rng.IntN(2)
			}
			k := math.Exp(math.Log(0.2) + rng.Float64()*(math.Log(2.5)-math.Log(0.2)))
			sys, _ := nearSingularEDraw(t, rng, n, m, p, k)
			v := "plain"
			if !matlabRankFull(t, sys.E) {
				v = "rankdef"
			}
			out = append(out, lsR3Case{set.name, v, seed, sys})
			if m != 1 || p != 1 {
				continue
			}
			if _, ok := foldInaccurateParts(sys); !ok {
				continue
			}
			ds := sys.Copy()
			ds.InputDelay, ds.OutputDelay = []float64{0.2}, []float64{0.3}
			out = append(out, lsR3Case{set.name, "iodelay", seed, ds})
			fr := sys.Copy()
			fr.InputDelay = []float64{0.05}
			out = append(out, lsR3Case{set.name, "fracdelay", seed, fr})
			pd := sys.Copy()
			pd.Delay = mat.NewDense(1, 1, []float64{0.2})
			out = append(out, lsR3Case{set.name, "pathdelay", seed, pd})
			sc := sys.Copy()
			sc.A.Scale(7, sc.A)
			sc.E.Scale(7, sc.E)
			out = append(out, lsR3Case{set.name, "scaled7", seed, sc})
		}
	}
	return out
}

func lsR3OtherCases() []lsR3Case {
	var out []lsR3Case
	for seed := range uint64(200) {
		rng := rand.New(rand.NewPCG(seed, 31337))
		n := 1 + rng.IntN(6)
		a, b, c, d, e := mat.NewDense(n, n, nil), mat.NewDense(n, 1, nil), mat.NewDense(1, n, nil), mat.NewDense(1, 1, []float64{rng.NormFloat64()}), mat.NewDense(n, n, nil)
		for i := range n {
			for j := range n {
				a.Set(i, j, rng.NormFloat64())
				e.Set(i, j, 0.3*rng.NormFloat64())
			}
			e.Set(i, i, e.At(i, i)+1)
			b.Set(i, 0, rng.NormFloat64())
			c.Set(0, i, rng.NormFloat64())
		}
		ex, _ := New(mat.DenseCopyOf(a), mat.DenseCopyOf(b), mat.DenseCopyOf(c), mat.DenseCopyOf(d), 0)
		out = append(out, lsR3Case{"explicit", "plain", seed, ex})
		ds, err := NewDescriptor(a, b, c, d, e, 0)
		if err != nil {
			continue
		}
		out = append(out, lsR3Case{"wellE", "plain", seed, ds})
		e2 := mat.DenseCopyOf(e)
		e2.Set(n-1, n-1, e2.At(n-1, n-1)*1e-5)
		if ds2, err := NewDescriptor(a, b, c, d, e2, 0); err == nil {
			out = append(out, lsR3Case{"midE", "plain", seed, ds2})
		}
	}
	return out
}

func lsR3Core(sys *System) *System {
	core := sys.Copy()
	core.InputDelay, core.OutputDelay, core.Delay = nil, nil, nil
	return core
}

func TestZZLSR3Probe(t *testing.T) {
	out := os.Getenv("LSR3_OUT")
	if out == "" {
		t.Skip()
	}
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	enc := json.NewEncoder(f)
	const dt = 0.1
	opt := C2DOptions{Method: C2DMethodLeastSquares}
	errs := func(e error) string {
		if e == nil {
			return ""
		}
		return e.Error()
	}
	cases := append(lsR3NSCases(t), lsR3OtherCases()...)
	for _, c := range cases {
		sys := c.Sys
		row := lsR3Row{Set: c.Set, Variant: c.Variant, Seed: c.Seed, FitPen: -1}
		row.N, row.M, row.P = sys.Dims()
		_, row.Routed = foldInaccurateParts(lsR3Core(sys))
		d, err := sys.C2D(dt, opt)
		row.Err, row.Hash = errs(err), lsR3Hash(d)
		if err == nil {
			row.Stable, _ = d.IsStable()
			if pl, err := d.Poles(); err == nil {
				for _, z := range pl {
					row.MaxPole = math.Max(row.MaxPole, cmplx.Abs(z))
				}
			}
			row.DOrder, _, _ = d.Dims()
			if row.DOrder > 0 {
				row.NormAd1 = mat.Norm(d.A, 1)
			}
			if row.M == 1 && row.P == 1 && sys.IsDescriptor() {
				core := sys.Copy()
				core.InputDelay, core.OutputDelay = nil, nil
				row.FitPen = lsR3MaxErr(t, d, core, dt)
			}
		}
		df, fit, err := sys.C2DFit(dt, opt)
		row.FitErr, row.FitHash = errs(err), lsR3Hash(df)
		row.FitMax, row.FitRMS = lsR3Fin(fit.MaxRelativeError), lsR3Fin(fit.RMSRelativeError)
		row.OtherHash = map[string]string{}
		for _, meth := range []C2DMethod{C2DMethodZOH, C2DMethodTustin, C2DMethodFOH, C2DMethodImpulse, C2DMethodMatched} {
			d, err := sys.C2D(dt, C2DOptions{Method: meth})
			row.OtherHash[string(meth)] = lsR3Hash(d) + "|" + errs(err)
		}
		if row.M == 1 && row.P == 1 {
			row.Ns = lsR3Time(sys, dt, opt)
		}
		enc.Encode(row)
	}
}
