### zz_r3_band_test.go.txt
```
package controlsys

// Round-3 band generator (3PWI4Q), branch only. For each routed SISO row
// (variants plain and scaled7, branch C2D error-free) it reruns the branch
// least-squares routine (a verbatim copy of leastSquaresFit, auto order)
// with the pencil target perturbed as target[k] *= 1 + 1e-15*(g1 + i g2),
// g1, g2 ~ N(0,1) from the row's rng, and records the fit-vs-pencil error
// lsR3MaxErr of every draw. Stage 1: 30 draws, PCG(seed,9001). Stage 2,
// only for rows outside stage 1: K draws, PCG(seed,9002), K = 4N-1 with N
// the band-row count of that set on this run (LSR3_K=set:K overrides).
// A zero-noise draw must reproduce the C2D hash (Selfcheck).
// LSR3_BAND=file writes one JSON line per row.

import (
	"encoding/json"
	"fmt"
	"math"
	"math/rand/v2"
	"os"
	"strconv"
	"strings"
	"testing"
)

func lsR3NoisyFit(sys *System, dt float64, rng *rand.Rand, rel float64) (*System, error) {
	fitOrder := 0
	pencil, slow := leastSquaresPencilParts(sys)
	sys, _, err := conversionStandardForm(sys, "descriptor reduction")
	if err != nil {
		return nil, err
	}
	n, _, _ := sys.Dims()
	if fitOrder == 0 {
		fitOrder = n
	}
	work := sys.Copy()
	work.InputDelay, work.OutputDelay, work.Delay = nil, nil, nil
	source, detect := work, work
	if pencil != nil {
		source, detect = pencil, slow
	}
	integrators, residue, err := leastSquaresIntegratorLimit(detect)
	if err != nil {
		return nil, err
	}
	if integrators > fitOrder {
		return nil, ErrInvalidOrder
	}
	samples := max(513, 32*fitOrder+1)
	omega := make([]float64, samples)
	for k := range samples {
		theta := math.Pi * float64(k) / float64(samples-1)
		if integrators > 0 {
			theta = math.Pi * (float64(k) + .5) / float64(samples)
		}
		omega[k] = theta / dt
	}
	target, err := leastSquaresSourceResponse(source, omega)
	if err != nil {
		return nil, err
	}
	if rng != nil {
		for k := range target {
			target[k] *= 1 + complex(rel*rng.NormFloat64(), rel*rng.NormFloat64())
		}
	}
	var realized *System
	if integrators > 0 {
		numerator, denominator, err := fitDiscreteIntegrators(target, fitOrder, integrators, residue*math.Pow(dt, float64(integrators)))
		if err != nil {
			return nil, err
		}
		realized, err = realizeDiscreteIntegrators(numerator, denominator, integrators, dt)
		if err != nil {
			return nil, err
		}
	} else {
		numerator, denominator, err := fitDiscreteResponse(target, fitOrder)
		if err != nil {
			return nil, err
		}
		fitted := &TransferFunc{Num: [][][]float64{{numerator}}, Den: [][]float64{denominator}, Dt: dt}
		result, err := fitted.stateSpace()
		if err != nil {
			return nil, err
		}
		realized = result.Sys
	}
	out, err := newDelayConversionPolicy(dt).applyDiscreteDelayFields(realized, sys)
	if err != nil {
		return nil, err
	}
	propagateNames(out, sys)
	out.StateName = nil
	return out, nil
}

type lsR3BandRow struct {
	Set, Variant      string
	Seed              uint64
	Parts             int
	Selfcheck         bool
	Branch            float64
	S1Min, S1Max      float64
	S1In              bool
	S1Draws           []float64
	K                 int
	S2Min, S2Max      float64
	S2In              bool
	S2Draws           []float64
	Fail              bool
	DrawErrs1, DrawE2 int
}

func lsR3Band(t *testing.T, sys *System, dt float64, seed, stream uint64, k int) ([]float64, int) {
	rng := rand.New(rand.NewPCG(seed, stream))
	core := lsR3Core(sys)
	var errs []float64
	fails := 0
	for range k {
		d, err := lsR3NoisyFit(core, dt, rng, 1e-15)
		if err != nil {
			fails++
			errs = append(errs, 1e300)
			continue
		}
		errs = append(errs, lsR3MaxErr(t, d, core, dt))
	}
	return errs, fails
}

func lsR3MinMax(v []float64) (float64, float64) {
	lo, hi := math.Inf(1), math.Inf(-1)
	for _, x := range v {
		lo, hi = math.Min(lo, x), math.Max(hi, x)
	}
	return lo, hi
}

func TestZZLSR3Band(t *testing.T) {
	out := os.Getenv("LSR3_BAND")
	if out == "" {
		t.Skip()
	}
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	enc := json.NewEncoder(f)
	override := map[string]int{}
	for _, kv := range strings.Split(os.Getenv("LSR3_K"), ",") {
		if s, v, ok := strings.Cut(kv, ":"); ok {
			override[s], _ = strconv.Atoi(v)
		}
	}
	const dt = 0.1
	opt := C2DOptions{Method: C2DMethodLeastSquares}
	var rows []*lsR3BandRow
	sysOf := map[*lsR3BandRow]*System{}
	nSet := map[string]int{}
	for _, c := range lsR3NSCases(t) {
		if c.Variant != "plain" && c.Variant != "scaled7" {
			continue
		}
		if _, m, p := c.Sys.Dims(); m != 1 || p != 1 {
			continue
		}
		parts, ok := foldInaccurateParts(lsR3Core(c.Sys))
		if !ok {
			continue
		}
		d, err := c.Sys.C2D(dt, opt)
		if err != nil {
			continue
		}
		row := &lsR3BandRow{Set: c.Set, Variant: c.Variant, Seed: c.Seed, Parts: len(parts)}
		core := lsR3Core(c.Sys)
		row.Branch = lsR3MaxErr(t, d, core, dt)
		if z, err := lsR3NoisyFit(core, dt, nil, 0); err == nil {
			row.Selfcheck = lsR3Hash(z) == lsR3Hash(d)
		}
		row.S1Draws, row.DrawErrs1 = lsR3Band(t, c.Sys, dt, c.Seed, 9001, 30)
		row.S1Min, row.S1Max = lsR3MinMax(row.S1Draws)
		row.S1In = row.S1Min <= row.Branch && row.Branch <= row.S1Max
		rows = append(rows, row)
		sysOf[row] = c.Sys
		nSet[c.Set]++
	}
	for _, row := range rows {
		if !row.S1In {
			row.K = 4*nSet[row.Set] - 1
			if k, ok := override[row.Set]; ok {
				row.K = k
			}
			row.S2Draws, row.DrawE2 = lsR3Band(t, sysOf[row], dt, row.Seed, 9002, row.K)
			row.S2Min, row.S2Max = lsR3MinMax(row.S2Draws)
			row.S2In = row.S2Min <= row.Branch && row.Branch <= row.S2Max
			row.Fail = !row.S2In
		}
		enc.Encode(row)
	}
	fmt.Println("band rows per set:", nSet)
}
