### zz_w56rev3_flip_test.go.txt
```
package controlsys

import (
	"fmt"
	"math"
	"math/cmplx"
	"math/rand/v2"
	"os"
	"testing"
)

func TestZZRev3Flip(t *testing.T) {
	if os.Getenv("REV3") == "" {
		t.Skip()
	}
	const dt = 0.1
	for _, c := range []struct {
		set    string
		stream uint64
		seed   uint64
		sc     bool
	}{{"ns400", 7704, 54, false}, {"ns400", 7704, 315, false}, {"ns1600", 9911, 68, false}, {"ns1600", 9911, 103, false}, {"ns1600", 9911, 1228, false}, {"ns1600", 9911, 290, true}, {"ns400", 7704, 296, false}, {"ns400", 7704, 71, false}, {"ns400", 7704, 194, false}, {"ns400", 7704, 279, true}, {"ns1600", 9911, 1094, true}} {
		rng := rand.New(rand.NewPCG(c.seed, c.stream))
		n := 2 + rng.IntN(5)
		m, p := 1, 1
		if rng.IntN(3) == 0 {
			m, p = 1+rng.IntN(2), 1+rng.IntN(2)
		}
		k := math.Exp(math.Log(0.2) + rng.Float64()*(math.Log(2.5)-math.Log(0.2)))
		sys, twin := nearSingularEDraw(t, rng, n, m, p, k)
		if c.sc {
			sys.A.Scale(7, sys.A)
			sys.E.Scale(7, sys.E)
			twin.A.Scale(7, twin.A)
			twin.E.Scale(7, twin.E)
		}
		var cp []float64
		for i := range n {
			cp = append(cp, twin.A.At(i, i)/twin.E.At(i, i))
		}
		_, routed := foldInaccurateParts(sys)
		d, err := sys.C2D(dt, C2DOptions{Method: C2DMethodLeastSquares})
		if err != nil {
			fmt.Printf("%s %d err %v\n", c.set, c.seed, err)
			continue
		}
		pl, _ := d.Poles()
		mx := 0.0
		pin := 0
		for _, z := range pl {
			mx = math.Max(mx, cmplx.Abs(z))
			if cmplx.Abs(z-1) < 1e-9 {
				pin++
			}
		}
		dn, _, _ := d.Dims()
		fmt.Printf("%s sc=%v seed %d routed=%v n=%d contpoles %.4g | dorder %d max|z| %.10f pinned@1 %d fitpen %.4g poles %.5g\n", c.set, c.sc, c.seed, routed, n, cp, dn, mx, pin, lsPencilFitError(t, d, twin, dt), pl)
	}
}
