### analyze.py
```
import json, sys
from fractions import Fraction
from collections import defaultdict

base_f, br_f, band_f, arch = sys.argv[1:5]
EPS = 2.0 ** -52
load = lambda p: [json.loads(l) for l in open(p)]
key = lambda r: (r['Set'], r['Variant'], r['Seed'])
base = {key(r): r for r in load(base_f)}
br = {key(r): r for r in load(br_f)}
band = load(band_f)
assert base.keys() == br.keys(), 'case sets differ'
print(f'== arch {arch}: cases {len(br)}')

print('-- (a) band census (rows = routed SISO plain+scaled7, branch C2D ok)')
bys = defaultdict(list)
for r in band:
    bys[r['Set']].append(r)
for s in sorted(bys):
    rs = bys[s]
    N = len(rs)
    ks = sorted({r['K'] for r in rs if r['K']})
    s2 = [r for r in rs if not r['S1In']]
    fails = [r for r in rs if r['Fail']]
    sc = sum(not r['Selfcheck'] for r in rs)
    p1 = sum(r['Parts'] == 1 for r in rs)
    derr = sum(r['DrawErrs1'] + r['DrawE2'] for r in rs)
    print(f'{s:7s} N={N} K={ks or [4*N-1]} stage1-in {N-len(s2)}/{N} stage2 {len(s2)} FAIL {len(fails)} selfcheck-mismatch {sc} parts==1 {p1} draw-errors {derr}')
    for r in s2:
        print(f'   {s} {r["Variant"]:8s} seed {r["Seed"]:5d} branch {r["Branch"]:.6g} S1 [{r["S1Min"]:.6g},{r["S1Max"]:.6g}] S2(K={r["K"]}) [{r["S2Min"]:.6g},{r["S2Max"]:.6g}] {"FAIL" if r["Fail"] else "pass"}')

print('-- (b) stability margin: base-stable rows with branch max|z| > 1')
nb = defaultdict(int)
for k, b in sorted(br.items()):
    a = base[k]
    if a['Err'] or b['Err'] or not a['Stable'] or b['MaxPole'] <= 1:
        continue
    m = b['DOrder'] * EPS * b['NormAd1']
    ok = b['MaxPole'] - 1 <= m
    nb[(k[0], ok)] += 1
