package controlsys

// 6QU2G3 r3 Q1-Q4 probe on 775db84: stability-count parity detector
// (Uc = parts[0] poles with Re>=0; Ud = fitted poles not stable per
// poleStabilityTolerance; fires when Ud > Uc) over every rv6Cases row, with
// exact plant poles F_ii/W_ii from the twin. R3Q_OUT=file. Needs
// zz_r3_probe_test.go and zz_rv6_census_test.go.

import (
	"encoding/json"
	"math"
	"math/cmplx"
	"os"
	"testing"
)

type r3qRow struct {
	Set, Variant string
	Seed         uint64
	N, M, P      int
	Routed       bool
	Err, Hash    string
	FitHash      string
	Stable       bool
	MaxPole      float64
	DOrder       int
	Poles        [][2]float64
	Ud, Uc       int
	UdBoundary   int
	UcErr        string
	SlowPoles    [][2]float64
	NParts       int
	PartPoles    [][][2]float64
	TwinCont     []float64
	SysPoles     [][2]float64
	SysPolesErr  string
}

func r3qC(z []complex128) [][2]float64 {
	out := make([][2]float64, 0, len(z))
	for _, p := range z {
		out = append(out, [2]float64{real(p), imag(p)})
	}
	return out
}

func TestZZR3QDetector(t *testing.T) {
	out := os.Getenv("R3Q_OUT")
	if out == "" {
		t.Skip()
	}
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	enc := json.NewEncoder(f)
	const dt = 0.1
	opt := C2DOptions{Method: C2DMethodLeastSquares}
	for _, c := range rv6Cases(t) {
		sys := c.Sys
		r := r3qRow{Set: c.Set, Variant: c.Variant, Seed: c.Seed}
		r.N, r.M, r.P = sys.Dims()
		core := lsR3Core(sys)
		parts, routed := foldInaccurateParts(core)
		r.Routed = routed
		if routed {
			r.NParts = len(parts)
			for i, pt := range parts {
				pl, err := pt.Poles()
				if err != nil {
					if i == 0 {
						r.UcErr = err.Error()
					}
					continue
				}
				r.PartPoles = append(r.PartPoles, r3qC(pl))
				if i == 0 {
					r.SlowPoles = r3qC(pl)
					for _, p := range pl {
						if real(p) >= 0 {
							r.Uc++
						}
					}
				}
			}
		}
		if c.Twin != nil {
			n, _, _ := c.Twin.Dims()
			for i := range n {
				r.TwinCont = append(r.TwinCont, c.Twin.A.At(i, i)/c.Twin.E.At(i, i))
			}
		}
		if sp, err := core.Poles(); err == nil {
			r.SysPoles = r3qC(sp)
		} else {
			r.SysPolesErr = err.Error()
		}
		d, err := sys.C2D(dt, opt)
		if err != nil {
			r.Err = err.Error()
		} else {
			r.Hash = lsR3Hash(d)
			r.Stable, _ = d.IsStable()
			r.DOrder, _, _ = d.Dims()
			dd := d.Copy()
			dd.InputDelay, dd.OutputDelay, dd.Delay = nil, nil, nil
			pl, perr := dd.Poles()
			if perr != nil {
				r.Err = "poles: " + perr.Error()
			}
			r.Poles = r3qC(pl)
			for _, p := range pl {
				r.MaxPole = math.Max(r.MaxPole, cmplx.Abs(p))
				switch classifyPoleStability(p, false, poleStabilityTolerance(p)) {
				case poleClassStable:
				case poleClassBoundary:
					r.Ud++
					r.UdBoundary++
				default:
					r.Ud++
				}
			}
		}
		if df, _, err := sys.C2DFit(dt, opt); err == nil {
			r.FitHash = lsR3Hash(df)
		}
		if err := enc.Encode(r); err != nil {
			t.Fatal(err)
		}
	}
}
