func qzCase(t *testing.T, seed int, fracTau bool) *System {
	rng := rand.New(rand.NewPCG(uint64(seed), 99173))
	n := 2 + rng.IntN(4)
	m, p := 1+rng.IntN(2), 1+rng.IntN(2)
	orth := func() *mat.Dense {
		g := mat.NewDense(n, n, nil)
		for i := range n {
			for j := range n {
				g.Set(i, j, rng.NormFloat64())
			}
		}
		var qr mat.QR
		qr.Factorize(g)
		var q mat.Dense
		qr.QTo(&q)
		return &q
	}
	Q, Z := orth(), orth()
	Ta, Te := mat.NewDense(n, n, nil), mat.NewDense(n, n, nil)
	k := 4 + rng.Float64()*8
	for i := range n {
		Ta.Set(i, i, -(0.3 + 2.7*rng.Float64()))
		Te.Set(i, i, 0.5+rng.Float64())
		for j := i + 1; j < n; j++ {
			Ta.Set(i, j, 0.3*rng.NormFloat64())
			Te.Set(i, j, 0.3*rng.NormFloat64())
		}
	}
	Te.Set(n-1, n-1, math.Pow(10, -k))
	var A, E, tmp mat.Dense
	tmp.Mul(Q, Ta)
	A.Mul(&tmp, Z)
	tmp.Mul(Q, Te)
	E.Mul(&tmp, Z)
	g := func(r, c int, s float64) *mat.Dense {
		d := mat.NewDense(r, c, nil)
		for i := range r {
			for j := range c {
				d.Set(i, j, s*rng.NormFloat64())
			}
		}
		return d
	}
	sys, err := NewDescriptor(&A, g(n, m, 1), g(p, n, 1), g(p, m, 0.5), &E, 0)
	if err != nil {
		t.Fatal(err)
	}
	taus := []float64{0.3, 0.5, 0.25}
	if fracTau {
		taus = []float64{0.3137, 0.4421, 0.2713}
	}
	io := rng.IntN(4) == 0
	tau := []float64{taus[rng.IntN(len(taus))]}
	if err := sys.SetInternalDelay(tau, g(n, 1, 0.4), g(1, n, 0.4), g(p, 1, 0.5), g(1, m, 0.4), g(1, 1, 0)); err != nil {
		t.Fatal(err)
	}
	if io {
		sys.InputDelay = make([]float64, m)
		sys.InputDelay[0] = 0.2
		sys.OutputDelay = make([]float64, p)
		sys.OutputDelay[0] = 0.1
	}
	return sys
}
