type uegFit struct {
	Set, Variant, Src string
	Seed              uint64
	N, Order          int
	Routed            bool
	Err               string
	ContPoles         []float64
	MinFold, MinTwin  int
	SlowOrder, SlowMin, NParts int
	SlowPoles []float64
