	CancelRelIdx      int
	CancelRelErr      float64
	CancelRelStable   bool
	UnstableD         int
	UnstableC         int
}

func uegC(z complex128) [2]float64 { return [2]float64{real(z), imag(z)} }

func uegTwinExplicit(twin *System) *System {
	n, m, _ := twin.Dims()
	a, b := mat.DenseCopyOf(twin.A), mat.DenseCopyOf(twin.B)
	for i := range n {
		w := twin.E.At(i, i)
		for j := range n {
			a.Set(i, j, a.At(i, j)/w)
		}
		for j := range m {
			b.Set(i, j, b.At(i, j)/w)
		}
	}
	s, _ := New(a, b, mat.DenseCopyOf(twin.C), mat.DenseCopyOf(twin.D), 0)
	return s
}

func uegErr(t *testing.T, d, twin *System, dt float64, pr, zr complex128, cancel bool) float64 {
	worst := 0.0
	for q := 1; q < 200; q++ {
		th := math.Pi * float64(q) / 200
		e := cmplx.Exp(complex(0, th))
		g, err := d.EvalFr(e)
		if err != nil {
			return 1e300
		}
		v := g[0][0]
		if cancel {
			v *= (e - pr) / (e - zr)
		}
		w := pencilResponse(t, twin, complex(0, th/dt))[0][0]
		worst = math.Max(worst, cmplx.Abs(v-w)/math.Max(1, cmplx.Abs(w)))
	}
	if math.IsNaN(worst) || math.IsInf(worst, 0) {
		return 1e300
	}
	return worst
}

func uegPerms(n int, f func([]int)) {
	p := make([]int, n)
	for i := range p {
		p[i] = i
	}
	var rec func(k int)
	rec = func(k int) {
		if k == n {
			f(p)
			return
		}
		for i := k; i < n; i++ {
			p[k], p[i] = p[i], p[k]
			rec(k + 1)
			p[k], p[i] = p[i], p[k]
		}
	}
	rec(0)
}

func uegFill(t *testing.T, r *uegFit, d *System, twin *System, slow []complex128, dt float64) {
	pl, _ := d.Poles()
	zs, _ := d.Zeros()
	r.Stable, _ = d.IsStable()
	for _, p := range pl {
		r.Poles = append(r.Poles, uegC(p))
		if cmplx.Abs(p) > 1 {
			r.UnstableD++
		}
	}
	for _, z := range zs {
		r.Zeros = append(r.Zeros, uegC(z))
	}
	r.FitPen = uegErr(t, d, twin, dt, 0, 0, false)
	np := len(pl)
	for i, p := range pl {
		nz, nzi := 1e300, -1
		for j, z := range zs {
			if dd := cmplx.Abs(p - z); dd < nz {
				nz, nzi = dd, j
			}
		}
		npd := 1e300
		for j, q := range pl {
			if j != i {
				npd = math.Min(npd, cmplx.Abs(p-q))
			}
		}
		r.NearZero = append(r.NearZero, nz)
		r.NearZeroRel = append(r.NearZeroRel, nz/cmplx.Abs(p))
		r.NearZeroIdx = append(r.NearZeroIdx, nzi)
		r.NearPole = append(r.NearPole, npd)
	}
	r.Unmatched = -1
	if np == len(slow)+1 && np <= 7 {
		best := math.Inf(1)
		var bp []int
		uegPerms(np, func(p []int) {
			s := 0.0
			for k := range slow {
				s += cmplx.Abs(pl[p[k]] - slow[k])
			}
			if s < best {
				best, bp = s, append([]int(nil), p...)
			}
		})
		r.Unmatched = bp[np-1]
		r.MatchDist = make([]float64, np)
		for k := range slow {
			r.MatchDist[bp[k]] = cmplx.Abs(pl[bp[k]] - slow[k])
		}
		r.MatchDist[r.Unmatched] = -1
	}
	cancel := func(i int) (float64, bool, float64) {
		if i < 0 || r.NearZeroIdx[i] < 0 {
			return -1, false, -1
		}
		mx := 0.0
		for j, p := range pl {
			if j != i {
