	r.CancelRelIdx = -1
	bestRel := math.Inf(1)
	for i := range pl {
		if r.NearZeroRel[i] < bestRel {
			bestRel, r.CancelRelIdx = r.NearZeroRel[i], i
		}
	}
	r.CancelRelErr, r.CancelRelStable, _ = cancel(r.CancelRelIdx)
}

