package controlsys

// Wave-42 review sweep (IR5YOF). Generators:
//   ctrl:   near-singular E (sigma_min = c*eps*10^u, u in [0,5]), generic
//           (rotated) or triangular, random Q >= 0, R > 0, n 2..6, m 1..3.
//   unc:    block-triangular plant whose near-infinite mode a22/e22 is
//           exactly uncontrollable (B last row 0) or nearly (delta), then
//           rotated A'=UAV, E'=UEV, B'=UB.
//   reg:    E = I or well-conditioned E with an uncontrollable mode on,
//           near or beyond the boundary, rotated.
// Discrete rows: Dare (descriptor X) and Dlqr; continuous: Care and Lqr.
// Oracles: 320-bit doubling on the explicit model (discrete) and 320-bit
// Newton from the returned K (both domains), with 1-ulp spread.
// ZRW_OUT output jsonl, ZRW_SEEDS per generator/domain.

import (
	"encoding/json"
	"errors"
	"math"
	"math/big"
	"math/cmplx"
	"math/rand/v2"
	"os"
	"strconv"
	"sync"
	"testing"

	"plantcontrol.org/v1/gonum/mat"
)

type zrwRow struct {
	Gen    string  `json:"gen"`
	Seed   uint64  `json:"seed"`
	Dt     float64 `json:"dt"`
	API    string  `json:"api"`
	N      int     `json:"n"`
	Verd   bool    `json:"verd"`
	Err    string  `json:"err,omitempty"`
	Bnd    bool    `json:"bnd"`
	Acc    int     `json:"acc"`
	EX     float64 `json:"ex"`
	EK     float64 `json:"ek"`
	SX     float64 `json:"sx"`
	SK     float64 `json:"sk"`
	Conv   bool    `json:"conv"`
	Robust bool    `json:"robust"`
	DX     float64 `json:"dx"`
	DK     float64 `json:"dk"`
	DOK    bool    `json:"dok"`
	DRho   float64 `json:"drho"`
	CondE  float64 `json:"conde"`
	Delta  float64 `json:"delta"`
	CL     float64 `json:"cl"`
	CLOK   bool    `json:"clok"`
}

func zrwOrth(rng *rand.Rand, n int) *mat.Dense {
	g := mat.NewDense(n, n, nil)
	for i := range n {
		for j := range n {
			g.Set(i, j, rng.NormFloat64())
		}
	}
	var qr mat.QR
	qr.Factorize(g)
	var q mat.Dense
	qr.QTo(&q)
	return &q
}

func zrwSPD(rng *rand.Rand, n int, psd bool) *mat.Dense {
	g := mat.NewDense(n, n, nil)
	for i := range n {
		for j := range n {
			g.Set(i, j, rng.NormFloat64())
		}
	}
	var q mat.Dense
	q.Mul(g, g.T())
	if !psd {
		for i := range n {
			q.Set(i, i, q.At(i, i)+0.5)
		}
	} else {
		for i := range n {
			q.Set(i, i, q.At(i, i)+1e-3)
		}
	}
	for i := range n {
		for j := i + 1; j < n; j++ {
			v := 0.5 * (q.At(i, j) + q.At(j, i))
			q.Set(i, j, v)
			q.Set(j, i, v)
		}
	}
	return &q
}

type zrwCase struct {
	A, B, E, Q, R *mat.Dense
	delta         float64
}

func zrwGen(gen string, seed uint64, dt float64) zrwCase {
	rng := rand.New(rand.NewPCG(seed, 42420+uint64(len(gen))))
	n := 2 + rng.IntN(5)
	m := 1 + rng.IntN(3)
	if rng.IntN(2) == 0 {
		m = 1
	}
	A, B, E := mat.NewDense(n, n, nil), mat.NewDense(n, m, nil), mat.NewDense(n, n, nil)
	for i := range n {
		for j := range n {
			A.Set(i, j, rng.NormFloat64())
		}
		for j := range m {
			B.Set(i, j, rng.NormFloat64())
		}
	}
	Q, R := zrwSPD(rng, n, true), zrwSPD(rng, m, false)
	if rng.IntN(2) == 0 {
		Q, R = eyeDense(n), eyeDense(m)
	}
	smin := (0.5 + 1.5*rng.Float64()) * eps() * math.Pow(10, 5*rng.Float64())
	var delta float64
	switch gen {
	case "ctrl":
		if rng.IntN(2) == 0 {
			for i := range n {
				E.Set(i, i, 0.5+rng.Float64())
				for j := i + 1; j < n; j++ {
					E.Set(i, j, rng.NormFloat64())
				}
			}
			E.Set(n-1, n-1, smin)
		} else {
