// zrwHbCheck runs Hewer in 320 bits from K0 keeping the 320-bit K, then
// reports the 320-bit DARE residual of y and the decay of ‖Acl^(2^j)‖ for
// the 320-bit oracle K and for the returned float64 K.
func zrwHbCheck(A, B, Q, R, E, Kret *mat.Dense) {
	e := hbFrom(E)
	a, b := hbSolve(e, hbFrom(A)), hbSolve(e, hbFrom(B))
	q, r := hbFrom(Q), hbFrom(R)
	k := hbFrom(Kret)
	var y hbMat
	for range 60 {
		y = hewerDareHB(a, b, q, r, hbMat{}, k, 1)
		btx := hbMul(b.t(), y)
		k = hbSolve(hbAdd(r, hbMul(btx, b), 1), hbMul(btx, a))
	}
	ay := hbMul(hbMul(a.t(), y), a)
	res := hbAdd(hbAdd(ay, y, -1), q, 1)
	res = hbAdd(res, hbMul(hbMul(a.t(), y), hbMul(b, k)), -1)
	fmt.Printf("  hb residual %.3g  |A'YA| %.3g |Y| %.3g\n", zrwHbNorm(res), zrwHbNorm(ay), zrwHbNorm(y))
	pw := func(kk hbMat) string {
		c := hbAdd(a, hbMul(b, kk), -1)
		s := ""
		for j := range 7 {
			s += fmt.Sprintf(" ^%d:%.3g", 1<<j, zrwHbNorm(c))
			c = hbMul(c, c)
		}
		return s
	}
	fmt.Println("  oracle K (320-bit) closed-loop powers", pw(k))
	fmt.Println("  returned K closed-loop powers        ", pw(hbFrom(Kret)))
	yr := hbFrom(Kret)
	_ = yr
	if a.r == 2 {
		c := hbAdd(a, hbMul(b, k), -1)
		tr := new(big.Float).SetPrec(hbPrec).Add(c.at(0, 0), c.at(1, 1))
		det := new(big.Float).SetPrec(hbPrec).Mul(c.at(0, 0), c.at(1, 1))
		det.Sub(det, new(big.Float).SetPrec(hbPrec).Mul(c.at(0, 1), c.at(1, 0)))
		t, _ := tr.Float64()
		d, _ := det.Float64()
		fmt.Printf("  oracle K 320-bit tr %.6g det %.6g\n", t, d)
	}
}

