	cases := append(lsR3NSCases(t), lsR3OtherCases()...)
	for _, c := range cases {
		sys := c.Sys
		row := lsR3Row{Set: c.Set, Variant: c.Variant, Seed: c.Seed, FitPen: -1}
		row.N, row.M, row.P = sys.Dims()
		_, row.Routed = foldInaccurateParts(lsR3Core(sys))
		d, err := sys.C2D(dt, opt)
		row.Err, row.Hash = errs(err), lsR3Hash(d)
		if err == nil {
			row.Stable, _ = d.IsStable()
			if pl, err := d.Poles(); err == nil {
				for _, z := range pl {
