		sys := c.Sys
		row := rv6Row{lsR3Row: lsR3Row{Set: c.Set, Variant: c.Variant, Seed: c.Seed, FitPen: -1}, FitTwin: -1}
		row.N, row.M, row.P = sys.Dims()
		_, row.Routed = foldInaccurateParts(lsR3Core(sys))
		d, err := sys.C2D(dt, opt)
		row.Err, row.Hash = errs(err), lsR3Hash(d)
		siso := row.M == 1 && row.P == 1
		if err == nil {
			row.Stable, _ = d.IsStable()
			row.MaxPole, row.Poles = rv6PoleInfo(d)
			row.DOrder, _, _ = d.Dims()
			if row.DOrder > 0 {
				row.NormAd1 = mat.Norm(d.A, 1)
				row.NormAdF = mat.Norm(d.A, 2)
			}
			if siso && sys.IsDescriptor() {
				row.FitPen = lsR3MaxErr(t, d, lsR3Core(sys), dt)
				if c.Twin != nil && (c.Variant == "plain" || c.Variant == "rankdef" || c.Variant == "scaled7") {
					row.FitTwin = lsR3MaxErr(t, d, c.Twin, dt)
				}
			}
		}
		if siso && c.Twin != nil {
			tw := c.Twin.Copy()
			tw.InputDelay, tw.OutputDelay, tw.Delay = sys.InputDelay, sys.OutputDelay, sys.Delay
			order := 0
			if err == nil {
				order = row.DOrder
			}
			td, terr := tw.C2D(dt, C2DOptions{Method: C2DMethodLeastSquares, FitOrder: order})
			row.TwinErr = errs(terr)
			if terr == nil {
				row.TwinStable, _ = td.IsStable()
				row.TwinMaxPole, row.TwinPoles = rv6PoleInfo(td)
				row.TwinOrder, _, _ = td.Dims()
			}
		}
		df, fit, err := sys.C2DFit(dt, opt)
		row.FitErr, row.FitHash = errs(err), lsR3Hash(df)
		row.FitMax, row.FitRMS = lsR3Fin(fit.MaxRelativeError), lsR3Fin(fit.RMSRelativeError)
		row.OtherHash = map[string]string{}
		for _, meth := range []C2DMethod{C2DMethodZOH, C2DMethodTustin, C2DMethodFOH, C2DMethodImpulse, C2DMethodMatched} {
			d, err := sys.C2D(dt, C2DOptions{Method: meth})
			row.OtherHash[string(meth)] = lsR3Hash(d) + "|" + errs(err)
		}
		if siso {
			row.Ns = lsR3Time(sys, dt, opt)
		}
		enc.Encode(row)
	}
}
